using Bank.Payments.Adapters.In.Rest;
using Bank.Payments.Domain.Error;
using Bank.Payments.Domain.Model;
using Bank.Payments.Domain.Port;

namespace Bank.Payments.Application;

/// <summary>Application service of PayOrder (legacy dbo.sp_pago_orden).</summary>
public sealed class PayOrderService(
    OrderRepository orders,
    CompanyTariffRepository tariffs,
    ServiceRepository services,
    AccountRepository accounts,
    DebitGateway debits)
{
    // CHAR comparisons of the legacy ignore trailing spaces.
    private static string? Norm(string? value) => value?.TrimEnd(' ');

    // exec @w_return = proc: a procedure that sets no explicit status returns 0 in the legacy,
    // so a status the port leaves NULL is the status 0.
    private static int StatusOf(DebitResult result) => result.ReturnCode ?? 0;

    public PayOrderResponse Execute(PayOrderRequest request)
    {
        // Default of the legacy parameter @i_canal = 'WEB' when the caller sends no channel.
        var canal = request.Canal ?? "WEB";
        var tipoCuenta = Norm(request.TipoCuenta);
        var servicio = Norm(request.Servicio);

        // RULE-001: a NULL account type makes "not in" unknown, so it does not reject (as in the legacy).
        if (tipoCuenta != null && tipoCuenta != "CTE" && tipoCuenta != "AHO" && tipoCuenta != "VIR")
        {
            throw new BusinessError("ACCOUNT_TYPE_NOT_ALLOWED", "50001", "TIPO DE CUENTA NO PERMITIDO");
        }

        // RULE-003 / RULE-002
        var order = orders.FindByNumberAndCompany(request.Orden, request.Empresa);
        if (order == null)
        {
            throw new BusinessError("ORDER_NOT_FOUND", "50002", "ORDEN NO EXISTE");
        }

        // A NULL status makes the comparison unknown, so it does not reject.
        var estado = Norm(order.Status);
        if (estado != null && estado != "P")
        {
            throw new BusinessError("ORDER_NOT_PENDING", "50003", "ORDEN NO ESTA PENDIENTE");
        }

        // RULE-004
        decimal? tarifa = null;
        string? separada = null;
        var companyTariff = tariffs.FindByCompanyAndService(request.Empresa, request.Servicio);
        if (companyTariff != null)
        {
            tarifa = companyTariff.Value;
            separada = Norm(companyTariff.SeparateCharge);
        }
        else
        {
            var service = services.FindByCode(request.Servicio);
            if (service != null)
            {
                tarifa = service.Tariff;
                separada = "N";
            }
        }

        if (tarifa == null)
        {
            tarifa = 0m;
        }

        // RULE-005
        decimal? comision;
        if (Norm(canal) == "WEB")
        {
            comision = Math.Round(tarifa.Value / 2m, 2, MidpointRounding.AwayFromZero);
        }
        else
        {
            comision = tarifa;
        }

        if (servicio == "NOMINA")
        {
            comision = 0m;
        }

        // RULE-006
        decimal? total;
        if (separada == "S")
        {
            total = request.Valor;
        }
        else
        {
            total = request.Valor + comision;
        }

        // RULE-007: missing account or NULL balance leaves the balance NULL; comparisons are not true.
        var account = accounts.FindByNumberAndType(request.Cuenta, request.TipoCuenta);
        decimal? saldo = account?.Balance;

        var isVir = tipoCuenta == "VIR";
        if ((isVir && saldo < total)
            || (tipoCuenta != null && !isVir && saldo + 100.00m < total))
        {
            throw new BusinessError("INSUFFICIENT_FUNDS", "50004", "FONDOS INSUFICIENTES");
        }

        // RULE-008
        DebitResult? first;
        try
        {
            first = debits.Debit(request.Cuenta, request.TipoCuenta, total, "PAGO ORDEN");
        }
        catch (Exception)
        {
            throw new BusinessError("DEBIT_FAILED", "50005", "ERROR EN DEBITO");
        }

        if (first == null || StatusOf(first) != 0)
        {
            throw new BusinessError("DEBIT_FAILED", "50005", "ERROR EN DEBITO");
        }

        var movimiento = first.Movement;

        // RULE-009 / RULE-010
        if (separada == "S" && comision > 0)
        {
            DebitResult? second;
            try
            {
                second = debits.Debit(request.Cuenta, request.TipoCuenta, comision, "COMISION PAGO");
            }
            catch (Exception)
            {
                throw new BusinessError("COMMISSION_FAILED", "50006", "ERROR EN COMISION");
            }

            if (second == null || StatusOf(second) != 0)
            {
                throw new BusinessError("COMMISSION_FAILED", "50006", "ERROR EN COMISION");
            }
        }

        // RULE-011 / RULE-012
        int rows;
        try
        {
            rows = orders.MarkPaid(request.Orden, request.Empresa, request.FechaProceso, comision);
        }
        catch (Exception)
        {
            throw new BusinessError("ORDER_UPDATE_FAILED", "50007", "ERROR ACTUALIZANDO ORDEN");
        }

        if (rows == 0)
        {
            throw new BusinessError("ORDER_UPDATE_FAILED", "50007", "ERROR ACTUALIZANDO ORDEN");
        }

        // RULE-013
        return new PayOrderResponse(movimiento, "PAGO REALIZADO");
    }
}

